with base as (select *, date_add(opened_date, 63) as opened_date_plus_63d from accounts where opened_date < '2024-12-01'), agg as (select case when year(opened_date) < 2024 then 'before_2024' when year(opened_date) = 2024 then '2024' else 'after_2024' end as opened_cohort, account_type, sum(case when status = 'FROZEN' then balance else 0 end) as frozen_balance from base group by case when year(opened_date) < 2024 then 'before_2024' when year(opened_date) = 2024 then '2024' else 'after_2024' end, account_type) select opened_cohort, account_type, frozen_balance from agg;
